    function reveal(i){if(revealed[i]||flags[i]||ended)return;if(!placed)setup(i);revealed[i]=true;if(board[i]===-1){ended=true;draw();finishGame("Boom!","You uncovered a mine.");return}if(board[i]===0)neighbors(i).forEach(j=>{if(!revealed[j])reveal(j)});if(revealed.filter(Boolean).length===size*size-mines){ended=true;setScore(100);finishGame("Field cleared!","You found a safe path through every cell.")}draw()}
